  "tour.overview.title": "\u5FEB\u901F\u5F00\u59CB",
  "tour.overview.desc": "\u8BA4\u8BC6\u4E3B\u754C\u9762\uFF1A\u5DE6\u4FA7\u5BFC\u822A\u3001\u9876\u90E8\u680F\u3001\u5168\u5C40\u641C\u7D22\u4E0E\u8BBE\u7F6E\u3002",
  "tour.overview.rail.title": "\u5DE6\u4FA7\u5BFC\u822A",
  "tour.overview.rail.body": "\u5DE6\u4FA7\u7684\u5BFC\u822A\u680F\u662F\u5E94\u7528\u7684\u4E3B\u5165\u53E3\u3002\u4E94\u4E2A\u56FE\u6807\u5BF9\u5E94\u4E94\u4E2A\u9875\u9762\uFF1A\u65E5\u7A0B\u3001\u4EFB\u52A1\u3001\u5BF9\u8BDD\u3001\u77E5\u8BC6\u3001\u8BB0\u5FC6\u3002",
  "tour.overview.dock.title": "\u9875\u9762\u5207\u6362",
  "tour.overview.dock.body": "\u70B9\u51FB\u56FE\u6807\u5373\u53EF\u5207\u6362\u5230\u5BF9\u5E94\u9875\u9762\uFF1B\u518D\u6B21\u70B9\u51FB\u5F53\u524D\u56FE\u6807\u4F1A\u56DE\u5230\u4EFB\u52A1\u770B\u677F\u3002",
  "tour.overview.search.title": "\u5168\u5C40\u641C\u7D22",
  "tour.overview.search.body": "\u9876\u680F\u7684\u653E\u5927\u955C\u6253\u5F00\u5168\u5C40\u641C\u7D22\uFF08Cmd/Ctrl+K\uFF09\uFF0C\u53EF\u4EE5\u8DE8\u9879\u76EE\u641C\u7D22\u5BF9\u8BDD\u3001\u4EFB\u52A1\u3001\u77E5\u8BC6\u3001\u8BB0\u5FC6\u548C\u65E5\u7A0B\uFF0C\u4E5F\u80FD\u6267\u884C\u547D\u4EE4\u3002",
  "tour.overview.settings.title": "\u8BBE\u7F6E",
  "tour.overview.settings.body": "\u9F7F\u8F6E\u6309\u94AE\u6253\u5F00\u8BBE\u7F6E\u9762\u677F\uFF0C\u5305\u542B\u6A21\u578B\u3001\u5916\u89C2\u3001\u5FEB\u6377\u952E\u7B49 12 \u4E2A\u6807\u7B7E\u9875\u3002",
  "tour.overview.help.title": "\u5E2E\u52A9\u4E2D\u5FC3",
  "tour.overview.help.body": "\u95EE\u53F7\u6309\u94AE\u6253\u5F00\u5E2E\u52A9\u4E2D\u5FC3\uFF1A\u5FEB\u901F\u5F00\u59CB\u3001\u5FEB\u6377\u952E\u5217\u8868\uFF0C\u4EE5\u53CA\u6559\u7A0B\u4E2D\u5FC3\u5165\u53E3\u3002",
  "tour.overview.done.title": "\u5B8C\u6210",
  "tour.overview.done.body": "\u4F60\u5DF2\u7ECF\u8BA4\u8BC6\u4E3B\u754C\u9762\u4E86\u3002",
  "tour.overview.done.p1": "\u968F\u65F6\u53EF\u4EE5\u518D\u6253\u5F00\u6559\u7A0B\u4E2D\u5FC3\u56DE\u987E",
  "tour.overview.done.p2": "Cmd+K \u641C\u7D22\u3001Cmd+, \u6253\u5F00\u8BBE\u7F6E",
  "tour.chat-basics.title": "\u5BF9\u8BDD\u57FA\u7840",
  "tour.chat-basics.desc": "\u5B66\u4F1A\u4E0E Agent \u5BF9\u8BDD\uFF1A\u8F93\u5165\u3001\u6743\u9650\u6A21\u5F0F\u3001\u9644\u4EF6\u4E0E\u5DE5\u5177\u3002",
  "tour.chat-basics.composer.title": "\u8F93\u5165\u6846",
  "tour.chat-basics.composer.body": "\u5E95\u90E8\u8F93\u5165\u6846\u7528\u6765\u548C Agent \u5BF9\u8BDD\u3002\u8F93\u5165\u4E00\u53E5\u8BDD\u5E76\u56DE\u8F66\u5373\u53EF\u53D1\u9001\u2014\u2014\u8FD9\u4F1A\u521B\u5EFA\u4E00\u6761\u771F\u5B9E\u5BF9\u8BDD\u3002",
  "tour.chat-basics.perm.title": "\u6A21\u578B\u3001Agent \u4E0E\u6743\u9650",
  "tour.chat-basics.perm.body": "\u6A21\u578B\u6309\u94AE\u4F1A\u6253\u5F00\u9009\u62E9\u5668\uFF1A\u53EF\u4EE5\u5207\u6362\u6A21\u578B\u6216 Agent\uFF0C\u5E76\u9009\u62E9\u6743\u9650\u6A21\u5F0F\u2014\u2014\u4ECE\u300C\u6BCF\u6B21\u8BE2\u95EE\u300D\u5230\u300C\u5B8C\u5168\u81EA\u4E3B\u300D\u3002",
  "tour.chat-basics.attach.title": "\u9644\u4EF6",
  "tour.chat-basics.attach.body": "\u56DE\u5F62\u9488\u6309\u94AE\u53EF\u4EE5\u9644\u52A0\u6587\u4EF6\u6216\u56FE\u7247\uFF0CAgent \u4F1A\u8BFB\u53D6\u5B83\u4EEC\u4F5C\u4E3A\u4E0A\u4E0B\u6587\u3002",
  "tour.chat-basics.tools.title": "\u5DE5\u5177\u5F00\u5173",
  "tour.chat-basics.tools.body": "\u5DE5\u5177\u6309\u94AE\u5207\u6362\u5BF9\u8BDD\u9644\u5E26\u7684\u5185\u5BB9\uFF1A\u4EBA\u7269\u8BBE\u5B9A\u3001\u5DE5\u4F5C\u533A\u3001\u77E5\u8BC6\u5E93\u7B49\u3002",
  "tour.chat-basics.send.title": "\u53D1\u9001",
  "tour.chat-basics.send.body": "\u51C6\u5907\u597D\u540E\uFF0C\u8F93\u5165\u5E76\u53D1\u9001\u4F60\u7684\u7B2C\u4E00\u6761\u6D88\u606F\u3002",
  "tour.chat-basics.send.p1": "\u53D1\u9001\u4F1A\u6D88\u8017\u989D\u5EA6\u5E76\u4EA7\u751F\u771F\u5B9E\u5BF9\u8BDD\u8BB0\u5F55",
  "tour.chat-basics.send.p2": "\u4E4B\u540E\u53EF\u4EE5\u5728\u5BF9\u8BDD\u5217\u8868\u91CC\u5220\u9664\u5B83",
  "tour.chat-deep.title": "\u5BF9\u8BDD\u8FDB\u9636",
  "tour.chat-deep.desc": "\u53F3\u4FA7\u9762\u677F\u3001\u91CD\u8BD5\u3001\u6743\u9650\u8BF7\u6C42\u4E0E\u4EA4\u4E92\u5757\u3002",
  "tour.chat-deep.sidebar.title": "\u53F3\u4FA7\u9762\u677F",
  "tour.chat-deep.sidebar.body": "\u5BF9\u8BDD\u53F3\u4FA7\u7684\u9762\u677F\u5C55\u793A\u5F53\u524D\u4EFB\u52A1\u7684\u6982\u89C8\u3001\u8BA1\u5212\u3001\u6587\u4EF6\u3001\u4EA7\u7269\u4E0E\u5B9E\u65F6\u6D4F\u89C8\u5668\u3002",
  "tour.chat-deep.split.title": "\u5206\u5C4F",
  "tour.chat-deep.split.body": "\u628A\u4FA7\u680F\u7684\u9762\u677F\u5361\u62D6\u51FA\u6765\uFF0C\u5373\u53EF\u56FA\u5B9A\u4E3A\u72EC\u7ACB\u5206\u5C4F\u7A97\u683C\uFF1B\u7528\u628A\u624B\u53EF\u4EE5\u5207\u6362\u5DE6\u53F3\u4FA7\u5E76\u8C03\u6574\u5BBD\u5EA6\u3002\u73B0\u5728\u53EF\u4EE5\u8BD5\u7740\u62D6\u4E00\u4E2A\u51FA\u6765\uFF0C\u6216\u8DF3\u8FC7\u6B64\u6B65\u3002",
