  "tour.project-basics.desc": "\u521B\u5EFA\u3001\u5207\u6362\u4E0E\u7BA1\u7406\u9879\u76EE\u2014\u2014\u6BCF\u4E2A\u9879\u76EE\u6709\u72EC\u7ACB\u7684\u5DE5\u4F5C\u533A\u3001\u77E5\u8BC6\u5E93\u548C\u8BB0\u5FC6\u3002",
  "tour.project-basics.switcher.title": "\u9879\u76EE\u5207\u6362\u5668",
  "tour.project-basics.switcher.body": "\u9876\u680F\u7684\u9879\u76EE\u5207\u6362\u5668\u5728\u9879\u76EE\u4E4B\u95F4\u8DF3\u8F6C\u3002\u6BCF\u4E2A\u9879\u76EE\u6709\u72EC\u7ACB\u7684\u5DE5\u4F5C\u533A\u6587\u4EF6\u5939\u3001\u5BF9\u8BDD\u3001\u4EFB\u52A1\u3001\u77E5\u8BC6\u5E93\u548C\u8BB0\u5FC6\u3002",
  "tour.project-basics.new.title": "\u65B0\u5EFA\u9879\u76EE",
  "tour.project-basics.new.body": "\u6253\u5F00\u5207\u6362\u5668\u83DC\u5355\u5373\u53EF\u65B0\u5EFA\u9879\u76EE\uFF0C\u6216\u5BFC\u5165\u73B0\u6709\u6587\u4EF6\u5939\u3002",
  "tour.project-basics.new.p1": "\u4ECE\u96F6\u521B\u5EFA\u65F6\u6709\u6A21\u677F\u53EF\u9009",
  "tour.project-basics.new.p2": "\u6BCF\u4E2A\u9879\u76EE\u6307\u5B9A\u81EA\u5DF1\u7684\u5DE5\u4F5C\u533A\u8DEF\u5F84",
  "tour.project-basics.memory.title": "\u9879\u76EE\u8BB0\u5FC6",
  "tour.project-basics.memory.body": "\u5728\u8BB0\u5FC6\u9875\uFF0C\u8FD9\u4E2A\u6309\u94AE\u7F16\u8F91\u9879\u76EE\u7684\u5171\u4EAB\u8BB0\u5FC6\u2014\u2014Agent \u5728\u8BE5\u9879\u76EE\u4E2D\u59CB\u7EC8\u638C\u63E1\u7684\u77E5\u8BC6\u3002",
  "tour.project-basics.done.title": "\u5B8C\u6210",
  "tour.project-basics.done.body": "\u9879\u76EE\u662F\u627F\u8F7D\u4F60\u6240\u6709\u5DE5\u4F5C\u7684\u81EA\u7136\u5355\u4F4D\u3002",
