  "tour.chat-basics.voice.title": "\u8BED\u97F3\u8F93\u5165",
  "tour.chat-basics.voice.body": "\u9EA6\u514B\u98CE\u6309\u94AE\u53EF\u4EE5\u7528\u8BED\u97F3\u4EE3\u66FF\u6253\u5B57\u3002\u8BED\u97F3\u80FD\u529B\u53EF\u5728\u8BBE\u7F6E \u2192 \u672C\u5730\u80FD\u529B\u4E2D\u5F00\u5173\u3002",
